const payload = $input.first().json.body || $input.first().json;
const message = (payload.message || '').toLowerCase();
let intent = 'general';
if (/invoice|billing|payment|charge|refund|subscription/.test(message)) {
  intent = 'billing';
} else if (/error|server|workflow|api|crash|down|fail|timeout/.test(message)) {
  intent = 'technical';
} else if (/help|support|ticket|assist|contact/.test(message)) {
  intent = 'support';
}
return [{ json: { ...payload, intent } }];

const intent = $input.first().json.intent || 'general';
const clientId = $input.first().json.client_id;
const userMessage = $input.first().json.message || '';
const conversationId = $input.first().json.conversation_id || '';
const historyRows = $('Postgres: Load History').first().all().map(r => r.json);
const history = historyRows.map(r => `${r.role}: ${r.message}`).join('
');
const prompt = `Client ID: ${clientId}
Intent: ${intent}

Conversation History:
${history || 'No prior messages.'}

Current User Message:
${userMessage}

Provide helpful SAOS support response.`;
return [{ json: { client_id: clientId, intent, prompt, conversation_id: conversationId, user_message: userMessage } }];
